local y=tonumber(arg[1]) or tonumber(os.date("%Y")); local m=tonumber(arg[2]) or tonumber(os.date("%m")); print(os.date("%B %Y",os.time{year=y,month=m,day=1})); local w=os.date("*t",os.time{year=y,month=m,day=1}).wday; local days=os.date("*t",os.time{year=y,month=m+1,day=0}).day; print("Su Mo Tu We Th Fr Sa"); local line=string.rep("   ",w-1); for d=1,days do line=line..("%2d "):format(d); if (w+d-1)%7==0 then print(line); line="" end end if line~="" then print(line) end
